import {createGame,BUILD_FOOTPRINTS} from './feouda-engine.js?v=2.1.1';
import {createBattlefield} from './feouda-world.js?v=2.1.1';
import {FACTIONS,REGIONS,UNIT_TYPES,BUILDINGS,TECHS,MAP,BRIDGES,RESOURCE_NAMES,ERAS,regionAt} from './feouda-data.js?v=2.1.1';
import {icon,unitPortrait,crest} from './feouda-icons.js?v=2.1.1';

const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=0)=>Number(v||0).toLocaleString('el-CY',{maximumFractionDigits:d,minimumFractionDigits:d}),money=v=>'CY£ '+num(v,2),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const storage={getItem(k){try{return localStorage.getItem(k)}catch{return null}},setItem(k,v){localStorage.setItem(k,v)}};
const store=(k,v)=>{try{storage.setItem(k,v)}catch{}};
const game=createGame({storage}),regionById=Object.fromEntries(REGIONS.map(r=>[r.id,r]));
const view={panel:'realm',panelOpen:innerWidth>780,selection:{kind:'region',id:'home'},regionId:'home',armyIds:[],command:null,armyTab:'troops',buildTab:'civil',resourceFilter:'all',mapMode:'terrain',modal:null,modalResume:false,started:game.loaded||storage.getItem('feouda-welcomed-v1')==='1',ready:false,sound:storage.getItem('feouda-sound')==='1',quality:storage.getItem('feouda-quality')||((innerWidth<780)?'low':'high'),endingShown:false,pendingImport:null,rendererMode:null,placement:null,assetStatus:null};
let world=null,audioContext=null,lastRender=0,lastStep=performance.now(),lastLog=null,held=false,rendering=false,bootFailed=false;
const PANELS={realm:['ΤΟ ΣΥΜΒΟΥΛΙΟ ΤΗΣ ΑΡΓΥΡΗΣ ΔΡΥΟΣ','Η κυριαρχία σου'],build:['ΛΙΘΟΙ, ΞΥΛΟ ΚΑΙ ΑΝΘΡΩΠΟΙ','Οικοδόμηση'],economy:['ΟΙ ΑΝΘΡΩΠΟΙ ΤΗΣ ΓΗΣ','Πόροι & εργάτες'],army:['ΤΟ ΠΟΛΕΜΙΚΟ ΣΥΜΒΟΥΛΙΟ','Στρατός & διαταγές'],research:['Η ΓΝΩΣΗ ΧΤΙΖΕΙ ΤΟ ΑΥΡΙΟ','Τέχνες & πρόοδος'],chronicle:['Ο ΔΡΟΜΟΣ ΠΡΟΣ ΤΗΝ ΗΓΕΜΟΝΙΑ','Το χρονικό'],diplomacy:['ΟΙΚΟΙ, ΣΥΝΟΡΑ ΚΑΙ ΣΥΜΦΩΝΙΕΣ','Διπλωματία & εμπόριο']};
const NAV=[['realm','castle','Φέουδα'],['build','build','Έργα'],['economy','people','Εργάτες'],['army','army','Στρατός'],['research','research','Τέχνες'],['chronicle','scroll','Χρονικό'],['diplomacy','trade','Εμπόριο']];
const ORDER_NAMES={hold:'Φρουρά',move:'Σε πορεία',attack:'Επίθεση',capture:'Πολιορκία',retreat:'Υποχώρηση'};
const CIVIL=['houses','farm','lumberyard','quarry','mine','granary','market','well','infirmary'];
const MILITARY=['barracks','archery','stable','siege','walls'];
const prices={food:{buy:1.6,sell:.85},wood:{buy:2.1,sell:1.1},stone:{buy:2.7,sell:1.45},iron:{buy:4.8,sell:2.6}};
const time=v=>{v=Math.max(0,Math.ceil(v||0));return v<60?v+'δ':v<3600?Math.floor(v/60)+'λ '+v%60+'δ':Math.floor(v/3600)+'ω '+Math.floor(v%3600/60)+'λ'};
const progress=(value,total,color='')=>`<div class="meter ${color}"><i style="width:${clamp(total?value/total*100:0,0,100)}%"></i></div>`;
const costHtml=cost=>`<div class="cost">${Object.entries(cost||{}).filter(([,v])=>v>0).map(([k,v])=>`<span>${icon(k)}${k==='money'?'CY£ '+num(v):num(v)}</span>`).join('')}</div>`;
const preview=(action,payload)=>game.canCommand?.(action,payload)||{ok:true};
const owned=()=>REGIONS.filter(r=>game.state.regions[r.id]?.owner==='player');
const squads=()=>game.state.squads.filter(s=>s.owner==='player'&&s.hp>0);
const armyIds=()=>view.armyIds.filter(id=>squads().some(s=>s.id===id));
const ownedRegion=()=>game.state.regions[view.regionId]?.owner==='player'?regionById[view.regionId]:owned()[0];
const currentRegion=()=>regionById[view.selection.kind==='region'?view.selection.id:view.regionId]||regionById.home;
function tone(kind='select'){if(!view.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const t=audioContext.currentTime;const frequencies=kind==='error'?[115,90]:kind==='war'?[98,147,196]:kind==='success'?[247,330,392]:[196,294];frequencies.forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=kind==='war'?'triangle':'sine';o.frequency.setValueAtTime(f,t+i*.055);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.042,t+i*.055+.01);g.gain.exponentialRampToValueAtTime(.0001,t+i*.055+.2);o.connect(g);g.connect(audioContext.destination);o.start(t+i*.055);o.stop(t+i*.055+.25);});}catch{}}
function toast(message,error=false){if(!message)return;const d=document.createElement('div');d.className='toast'+(error?' error':'');d.innerHTML=icon(error?'warning':'check')+'<span>'+esc(message)+'</span>';$('toasts').append(d);while($('toasts').children.length>3)$('toasts').firstElementChild.remove();setTimeout(()=>d.remove(),4200);tone(error?'error':'success');}
function act(action,payload,quiet=false){const result=game.command(action,payload);if(!quiet||!result.ok)toast(result.message,!result.ok);render(true);return result;}
function setInsets(){const mobile=innerWidth<=780;world?.setInsets({left:mobile?0:82,right:!mobile&&view.panelOpen?(innerWidth>1550?377:350):0,top:mobile?142:135,bottom:mobile?173:130});}
function setPanel(id,open=true){view.panel=id;view.panelOpen=open;$('panel-body').scrollTop=0;render(true);setInsets();}
function updateInput(){world?.setInputEnabled(view.started&&!view.modal&&!bootFailed);for(const child of $('game-shell').children){if(child.id!=='modal-root')child.inert=!!view.modal;}}
function setSelection(selection,{open=false,focus=false,add=false}={}){if(!selection)return;if(selection.kind==='squad'){const s=game.state.squads.find(s=>s.id===selection.id);if(s?.owner==='player'){view.armyIds=add?[...new Set([...armyIds(),s.id])]:[s.id];selection={kind:'army',ids:[...view.armyIds]};}}else if(selection.kind==='army'){view.armyIds=(selection.ids||[]).filter(id=>squads().some(s=>s.id===id));selection={kind:'army',ids:[...view.armyIds]};}view.selection=selection;if(selection.kind==='structure'){const st=game.state.structures?.find(a=>a.id===selection.id);if(st){view.regionId=st.regionId;if(focus)world?.focus(st);}if(open){view.panel='build';view.panelOpen=true;}}if(selection.kind==='region'){view.regionId=selection.id;if(open){view.panel='realm';view.panelOpen=true;}if(focus)world?.focus(selection.id);}if(selection.kind==='node'){const n=game.state.nodes.find(n=>n.id===selection.id);if(n){view.regionId=n.regionId;if(focus)world?.focus(n);}if(open){view.panel='economy';view.panelOpen=true;}}world?.setSelection(selection);tone();render(true);setInsets();}
function placementPayload(){const p=view.placement;return p?{type:p.type,regionId:p.regionId,x:p.x,z:p.z,rotation:p.rotation}:null;}
function refreshPlacement(){
 const p=view.placement;if(!p)return;
 const quote=preview('build',placementPayload()),footprint=BUILD_FOOTPRINTS[p.type];p.quote=quote;
 world?.setPlacement({...p,...footprint,...quote.placement,valid:quote.ok});
 $('game-shell').dataset.placing=p.type;
}
function startPlacement(type,regionId){
 const quote=preview('build',{type,regionId});if(!quote.ok){toast(quote.message,true);return;}
 if(type==='walls'){act('build',{type,regionId});return;}
 const point=game.findBuildLocation(type,regionId,0)||regionById[regionId];
 view.command=null;view.regionId=regionId;view.panel='build';view.panelOpen=false;
 view.placement={type,regionId,x:point.x,z:point.z,rotation:0,anchored:false,quote};
 refreshPlacement();world?.focus(point);setInsets();render(true);
}
function movePlacement(point,anchor=false){
 const p=view.placement;if(!p||(!anchor&&p.anchored)||!Number.isFinite(point?.x)||!Number.isFinite(point?.z))return;
 p.x=point.x;p.z=point.z;p.anchored=anchor;refreshPlacement();renderDeck(game.state);renderAlerts(game.state);if(anchor)tone();
}
function cancelPlacement({open=true}={}){
 if(!view.placement)return;view.placement=null;world?.clearPlacement();delete $('game-shell').dataset.placing;
 if(open){view.panel='build';view.panelOpen=true;}render(true);setInsets();
}
function rotatePlacement(){const p=view.placement;if(!p)return;p.rotation=(p.rotation+Math.PI/2)%(Math.PI*2);refreshPlacement();renderDeck(game.state);renderAlerts(game.state);}
function confirmPlacement(){
 const p=view.placement;if(!p||!p.anchored)return;refreshPlacement();if(!p.quote.ok){toast(p.quote.message,true);render(true);return;}
 const before=new Set((game.state.structures||[]).map(a=>a.id)),result=game.command('build',placementPayload());
 if(!result.ok){toast(result.message,true);refreshPlacement();render(true);return;}
 const structure=game.state.structures.find(a=>!before.has(a.id));cancelPlacement({open:false});
 if(structure)setSelection({kind:'structure',id:structure.id});toast(result.message);render(true);
}
function placementDeck(){
 const p=view.placement,q=p.quote,b=BUILDINGS[p.type],angle=Math.round(p.rotation*180/Math.PI)%360;
 return `<div class="placement-copy"><span class="eyebrow">ΤΟΠΟΘΕΤΗΣΗ · ${esc(regionById[p.regionId].name)}</span><h3>${esc(b.name)}</h3><p class="placement-status ${q.ok?'valid':'invalid'}" role="status">${q.ok?(p.anchored?'Έτοιμο για κατασκευή.':'Πάτησε στον χάρτη για να ορίσεις θέση.'):esc(q.message)}</p>${costHtml(q.cost||b.cost)}<span class="placement-meta">${time(q.duration||b.time)} · ${angle}° · ${p.anchored?'Θέση επιλεγμένη':'Προεπισκόπηση'}</span></div><div class="placement-actions"><button class="button" data-action="placement-rotate" title="Περιστροφή 90° · R">↻ <span>Περιστροφή</span></button>${p.anchored?'<button class="button" data-action="placement-move">'+icon('move')+'<span>Άλλη θέση</span></button>':''}<button class="button brass" data-action="placement-confirm" ${q.ok&&p.anchored?'':'disabled'}>${icon('build')}<span>Χτίσε εδώ</span></button><button class="button placement-cancel" data-action="placement-cancel" aria-label="Ακύρωση τοποθέτησης">${icon('close')}<span>Ακύρωση</span></button></div>`;
}
function chooseArmy(type='all'){const ss=squads().filter(s=>type==='all'||s.type===type||UNIT_TYPES[s.type].role===type);setSelection({kind:'army',ids:ss.map(s=>s.id)});if(!ss.length)toast('Δεν διαθέτεις τέτοιο απόσπασμα.',true);}
function issue(point,target=null){const ids=armyIds();if(!ids.length){toast('Επίλεξε πρώτα ένα ή περισσότερα δικά σου αποσπάσματα.',true);return;}let type=view.command||'move',payload={ids,type,x:point?.x,z:point?.z};if(target?.kind==='squad'){const s=game.state.squads.find(s=>s.id===target.id);if(!s||s.hp<=0){toast('Ο στόχος δεν υπάρχει πια.',true);return;}if(s.owner!=='player'){payload={ids,type:'attack',targetId:s.id};}else payload={ids,type:'move',x:s.x,z:s.z};}else if(target?.kind==='region'){const r=regionById[target.id],owner=game.state.regions[r.id]?.owner;const hasInfantry=game.state.squads.some(s=>ids.includes(s.id)&&UNIT_TYPES[s.type].role==='infantry');payload=owner==='player'?{ids,type:'move',x:r.x,z:r.z+32}:{ids,type:view.command==='attack'||!hasInfantry?'attack':'capture',regionId:r.id};}else if(type==='attack'&&point){payload={ids,type:'move',x:point.x,z:point.z};}const result=act('order',payload);if(result.ok){view.command=null;setSelection({kind:'army',ids});tone('war');}render(true);}
function onMapSelect(selection,event){if(view.placement)return;if(view.command&&armyIds().length){let p=selection.kind==='region'?regionById[selection.id]:selection.kind==='node'?game.state.nodes.find(n=>n.id===selection.id):selection.kind==='structure'?game.state.structures.find(n=>n.id===selection.id):game.state.squads.find(s=>s.id===selection.id);issue(p,selection);return;}setSelection(selection,{open:selection.kind!=='squad',add:!!event?.shiftKey});}
// Keep icon nodes stable between simulation ticks so a press is not detached before click.
function renderControlIcon(id,name){const button=$(id);if(button.dataset.icon!==name){button.innerHTML=icon(name);button.dataset.icon=name;}}
function renderResources(s){const fields=['money','wood','stone','iron','food'];$('resource-bar').innerHTML=fields.map(k=>{let rate=k==='money'?(s.income||0)-(s.upkeep||0):k==='food'?(s.foodBalance||0):(s.gatherRates?.[k]||0);return `<button class="resource" data-action="resource" data-value="${k}" title="${esc(RESOURCE_NAMES[k])}">${icon(k)}<span><span class="number">${k==='money'?'CY£ ':''}${num(s.resources[k],k==='money'?0:0)}<small class="${rate<0?'negative':''}">${rate>=0?'+':''}${num(rate*60,1)}/λ</small></span><label>${k==='money'?'ΚΟΙΝΟ ΤΑΜΕΙΟ':k==='food'?'ΤΡΟΦΙΜΑ':k==='wood'?'ΞΥΛΕΙΑ':k==='stone'?'ΠΕΤΡΑ':'ΣΙΔΗΡΟΣ'}</label></span></button>`}).join('')+`<button class="resource population" data-action="panel" data-value="economy">${icon('people')}<span><span class="number">${num(s.population)} / ${num(s.housing)}<small>${num(s.availableWorkers)} ελεύθεροι</small></span><label>ΚΑΤΟΙΚΟΙ</label></span></button>`;}
function regionPicker(r){return `<div class="owner-line"><span class="crest">${crest('player')}</span><span><b>${esc(r?.name||'Χωρίς φέουδο')}</b><small>Επίλεξε άλλο δικό σου οχυρό στον χάρτη.</small></span></div>`;}
function realmPanel(s){const r=currentRegion(),rs=s.regions[r.id],owner=FACTIONS[rs.owner],here=s.squads.filter(u=>u.owner===rs.owner&&u.hp>0&&Math.hypot(u.x-r.x,u.z-r.z)<52),isOwn=rs.owner==='player',repairQuote=preview('repair',{regionId:r.id});return `<div class="owner-line"><span class="crest">${crest(rs.owner)}</span><span><b>${esc(r.name)}</b><small>${esc(owner.shortName)} · ${esc(r.subtitle)}</small></span></div><div class="stat-pair large"><span>Αντοχή οχυρού</span><b>${num(rs.fortHp)} <small>/ ${num(rs.maxFortHp)}</small></b></div>${progress(rs.fortHp,rs.maxFortHp,isOwn?'':'red')}<div class="stat-pair"><span>Αποσπάσματα κοντά</span><b>${here.length}</b></div>${rs.capture>0?`<div class="stat-pair"><span>Έλεγχος της πύλης</span><b>${num(rs.capture)}%</b></div>${progress(rs.capture,100,'gold')}`:''}<div class="button-row"><button class="button" data-action="focus-region" data-value="${r.id}">${icon('focus')}Εστίαση</button>${isOwn?`<button class="button" data-action="panel" data-value="build">${icon('build')}Έργα</button>`:`<button class="button red" data-action="besiege" data-value="${r.id}">${icon('attack')}Πολιορκία</button>`}</div>${isOwn?`<button class="button full small" data-action="repair" data-value="${r.id}" ${repairQuote.ok?'':'disabled'}>${icon('shield')}Επισκευή τειχών</button>${rs.fortHp<rs.maxFortHp?costHtml(repairQuote.cost):''}${s.jobs.filter(j=>j.regionId===r.id&&j.blocked).map(j=>`<p class="job-blocked" role="status">${esc(j.blockedReason||'Το έργο περιμένει να ελευθερωθεί ο χώρος.')}</p>`).join('')}<div class="section-title">ΟΙ ΑΝΘΡΩΠΟΙ ΤΗΣ ΗΓΕΜΟΝΙΑΣ</div><div class="stat-pair"><span>Ηθικό</span><b>${num(s.morale)} / 100</b></div>${progress(s.morale,100)}<div class="stat-pair"><span>Ευημερία</span><b>${num(s.prosperity)} / 100</b></div>${progress(s.prosperity,100,'gold')}<p class="panel-description" style="margin-top:13px">Στέγη, νερό και επαρκής τροφή βοηθούν τους οικισμούς να προοδεύουν. Κράτησε διαθέσιμα χέρια και για τα έργα σου.</p>`:`<p class="panel-description">Χρειάζεσαι γειτονικό δικό σου φέουδο για να κρατήσεις αυτή την περιοχή. Οι μηχανές γκρεμίζουν την οχύρωση· το πεζικό μπαίνει στο οχυρό και το καταλαμβάνει.</p>`}<div class="section-title">ΧΑΡΤΗΣ ΚΥΡΙΑΡΧΙΑΣ · ${owned().length}/9</div>${REGIONS.map(p=>{const a=s.regions[p.id];return `<div class="province-row" style="--faction-color:${FACTIONS[a.owner].color}"><span class="province-mark">${icon(p.kind==='castle'?'castle':'flag')}</span><span class="province-copy"><h3>${esc(p.name)}</h3><p>${esc(FACTIONS[a.owner].shortName)}</p></span><button data-action="select-region" data-value="${p.id}" aria-label="Επίλεξε ${esc(p.name)}">${icon('chevron')}</button></div>`}).join('')}`;}
function buildPanel(s){
 const r=ownedRegion();if(!r)return '<p class="empty">Χρειάζεσαι ένα δικό σου φέουδο.</p>';
 const existing=(s.structures||[]).filter(st=>st.regionId===r.id);
 return regionPicker(r)+`<p class="panel-description">Διάλεξε κτίριο, όρισε τη θέση του στον χάρτη και επιβεβαίωσε την κατασκευή. Τα υπάρχοντα κτίρια αναβαθμίζονται επιτόπου.</p><div class="category-tabs"><button data-action="build-tab" data-value="civil" class="${view.buildTab==='civil'?'active':''}">Οικισμός</button><button data-action="build-tab" data-value="military" class="${view.buildTab==='military'?'active':''}">Στρατός & τείχη</button></div>`+(view.buildTab==='civil'?CIVIL:MILITARY).map(type=>{
  const b=BUILDINGS[type],level=s.regions[r.id].buildings[type]||0,pr=preview('build',{type,regionId:r.id}),job=s.jobs.find(j=>j.kind==='build'&&j.type===type&&j.regionId===r.id),plots=existing.filter(a=>a.type===type);
  return `<article class="build-item"><div class="item-heading"><h3>${esc(b.name)}</h3><span class="level">${type==='walls'?'ΤΕΙΧΗ '+level:plots.length+' ΚΤΙΡΙΑ · ΙΣΧΥΣ '+level}</span></div><p>${esc(b.description)}</p><div class="benefit">${esc(b.benefit)}</div>${costHtml(pr.cost||b.cost)}${job?`${progress(job.duration-job.remaining,job.duration,'gold')}<p class="reason">Σε κατασκευή · ${time(job.remaining)}</p>`:`<button class="button full small" data-action="build" data-value="${type}" data-region="${r.id}" ${pr.ok?'':'disabled'}>${icon('build')}${type==='walls'?'Ενίσχυση τειχών':'Τοποθέτηση στον χάρτη'} · ${time(pr.duration||b.time)}</button>${!pr.ok?`<p class="reason">${esc(pr.message)}</p>`:''}`}${plots.length?`<div class="existing-plots">${plots.map((st,i)=>`<button data-action="select-structure" data-value="${st.id}" class="${view.selection.kind==='structure'&&view.selection.id===st.id?'selected':''}">${icon(st.status==='ready'?'focus':'build')}<span>${esc(b.name)} ${i+1}<small>${st.status==='ready'?'Βαθμίδα '+st.level:st.status==='upgrading'?'Αναβαθμίζεται':'Εργοτάξιο'}</small></span>${icon('chevron')}</button>`).join('')}</div>`:''}</article>`;
 }).join('');
}
function economyPanel(s){const nodes=s.nodes.filter(n=>s.regions[n.regionId]?.owner==='player'&&(view.resourceFilter==='all'||n.type===view.resourceFilter));return `<div class="assignment-summary"><span>Διαθέσιμοι εργάτες<br><b>${num(s.availableWorkers)}</b></span><span>Στους πόρους<br><b>${num(s.assignedWorkers)}</b></span><span>Σε έργα<br><b>${num(s.busyWorkers)}</b></span></div><p class="panel-description">Διάλεξε κοιτάσματα και χωράφια στον χάρτη. Το + αναθέτει έναν εργάτη· το − τον ελευθερώνει. Οι πόροι μεταφέρονται στο κοινό απόθεμα.</p><div class="category-tabs">${['all','food','wood','stone','iron'].map(k=>`<button data-action="resource-filter" data-value="${k}" class="${view.resourceFilter===k?'active':''}">${k==='all'?'Όλα':esc(RESOURCE_NAMES[k])}</button>`).join('')}</div>${nodes.map(n=>`<article class="resource-node ${view.selection.kind==='node'&&view.selection.id===n.id?'node-selected':''}"><button class="node-symbol" data-action="focus-node" data-value="${n.id}" title="Εστίαση στον πόρο">${icon(n.type)}</button><span><h3>${esc(RESOURCE_NAMES[n.type])}</h3><small>${esc(regionById[n.regionId].name)} · ${num(n.amount)} υπόλοιπο</small></span><span class="node-controls"><button data-action="worker" data-value="${n.id}" data-delta="-1" aria-label="Αφαίρεσε εργάτη από ${esc(n.id)}" ${n.workers?'':'disabled'}>−</button><b>${n.workers}</b><button data-action="worker" data-value="${n.id}" data-delta="1" aria-label="Πρόσθεσε εργάτη στο ${esc(n.id)}" ${preview('assignWorkers',{nodeId:n.id,delta:1}).ok?'':'disabled'}>+</button></span></article>`).join('')}<div class="section-title">ΤΡΟΦΗ & ΣΥΝΤΗΡΗΣΗ</div><div class="stat-pair"><span>Τρόφιμα / λεπτό</span><b>${num((s.foodBalance||0)*60,1)}</b></div><div class="stat-pair"><span>Εισφορές / λεπτό</span><b>${money((s.income||0)*60)}</b></div><div class="stat-pair"><span>Συντήρηση / λεπτό</span><b>${money((s.upkeep||0)*60)}</b></div>`;}
function armyPanel(s){const r=ownedRegion(),all=squads(),selected=armyIds();return `<div class="stat-pair"><span>Άνδρες σε αποσπάσματα</span><b>${num(s.armyUsed)} / ${num(s.armyCapacity)}</b></div><div class="category-tabs"><button data-action="army-tab" data-value="troops" class="${view.armyTab==='troops'?'active':''}">Στο πεδίο (${all.length})</button><button data-action="army-tab" data-value="train" class="${view.armyTab==='train'?'active':''}">Στρατολόγηση</button></div>${view.armyTab==='troops'?`<div class="button-row"><button class="button small" data-action="select-army" data-value="all">Όλος ο στρατός</button><button class="button small" data-action="select-army" data-value="siege">Μηχανές</button></div><div class="army-list">${all.map(u=>`<button class="army-row ${selected.includes(u.id)?'selected':''}" data-action="select-squad" data-value="${u.id}" title="Shift + πάτημα για πολλαπλή επιλογή"><span class="portrait">${unitPortrait(u.type)}</span><span class="army-info"><b>${esc(UNIT_TYPES[u.type].name)}</b><small>${esc(ORDER_NAMES[u.order?.type]||'Σε αναμονή')} · ${num(u.hp)} αντοχή</small>${progress(u.hp,u.maxHp)}</span><span class="count">${u.men}</span></button>`).join('')}</div><p class="reason">Δεξί κλικ σε έδαφος ή αντίπαλο δίνει διαταγή. Στο κινητό διάλεξε αποσπάσματα και πάτησε Πορεία ή Επίθεση στο κάτω μέρος. Shift + σύρσιμο επιλέγει ομάδα.</p>`:r?regionPicker(r)+Object.entries(UNIT_TYPES).map(([type,u])=>{const pr=preview('train',{type,regionId:r.id});return `<article class="train-card"><span class="portrait">${unitPortrait(type)}</span><div><h3>${esc(u.name)}</h3><p>${esc(u.description)}</p>${costHtml(pr.cost||u.cost)}<button class="button full small" data-action="train" data-value="${type}" data-region="${r.id}" ${pr.ok?'':'disabled'}>${icon('army')}Εκπαίδευση · ${time(pr.duration||u.trainTime)}</button>${!pr.ok?`<p class="reason">${esc(pr.message)}</p>`:''}</div></article>`}).join(''):'<p class="empty">Δεν ελέγχεις οχυρό για εκπαίδευση.</p>'}`;}
function researchPanel(s){return `<p class="panel-description">Οι τέχνες της εποχής βελτιώνουν ολόκληρη την ηγεμονία. Η Μηχανική αντιβάρου ξεκλειδώνει τα τρεμπουσέ.</p>${Object.entries(TECHS).map(([type,t])=>{const level=s.techs[type]||0,pr=preview('research',{type}),job=s.jobs.find(j=>j.kind==='research'&&j.type===type);return `<article class="research-item"><div class="item-heading"><h3>${esc(t.name)}</h3><span class="level">${level}/${t.max}</span></div><p>${esc(t.description)}</p><div class="benefit">${esc(t.benefit)}</div>${costHtml(pr.cost||t.cost)}${job?`${progress(job.duration-job.remaining,job.duration,'gold')}<p class="reason">Μελέτη σε εξέλιξη · ${time(job.remaining)}</p>`:`<button class="button full small" data-action="research" data-value="${type}" ${pr.ok?'':'disabled'}>${icon('research')}Μελέτη · ${time(pr.duration||t.time)}</button>${!pr.ok?`<p class="reason">${esc(pr.message)}</p>`:''}`}</article>`}).join('')}`;}
function chroniclePanel(s){return `<div class="owner-line"><span class="crest">${crest('player')}</span><span><b>${esc(ERAS[s.era]||ERAS[0])}</b><small>${s.missions.filter(m=>m.done).length} / ${s.missions.length} στόχοι επιτεύχθηκαν</small></span></div>${s.missions.map(m=>`<article class="mission ${m.done?'done':''}"><h3>${m.done?'✓ ':''}${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="mission-progress"><span>${m.done?'ΕΠΙΤΕΥΧΘΗΚΕ':'ΣΕ ΕΞΕΛΙΞΗ'}</span><span>${num(m.progress)} / ${m.target}</span></div>${progress(m.progress,m.target,'gold')}${m.reward&&Object.keys(m.reward).length?costHtml(m.reward):''}</article>`).join('')}<div class="section-title">ΑΝΑΦΟΡΕΣ ΑΓΓΕΛΙΟΦΟΡΩΝ</div>${s.log.slice(0,20).map(l=>`<article class="log-entry"><small>ΗΜΕΡΑ ${Math.floor(l.t/600)+1} · ${time(l.t%600)}</small><h3>${esc(l.title)}</h3><p>${esc(l.text)}</p></article>`).join('')}`;}
function diplomacyPanel(s){return `<p class="panel-description">Η κυπριακή λίρα είναι το κοινό νόμισμα αυτής της φανταστικής εκστρατείας. Αντάλλαξε πλεόνασμα με χρήματα ή εξασφάλισε χρόνο με μια προσωρινή συμφωνία.</p><div class="section-title">ΕΜΠΟΡΙΟ · ΠΑΡΤΙΔΑ 25</div>${['food','wood','stone','iron'].map(k=>`<div class="trade-row">${icon(k)}<span>${esc(RESOURCE_NAMES[k])}<small>Απόθεμα ${num(s.resources[k])}</small></span><button class="button small" data-action="trade" data-value="${k}" data-trade="buy" ${preview('trade',{resource:k,type:'buy',amount:25}).ok?'':'disabled'}>+25<br>CY£${num(prices[k].buy*25)}</button><button class="button small" data-action="trade" data-value="${k}" data-trade="sell" ${preview('trade',{resource:k,type:'sell',amount:25}).ok?'':'disabled'}>−25<br>CY£${num(prices[k].sell*25)}</button></div>`).join('')}<div class="section-title">ΟΙ ΑΝΤΙΠΑΛΟΙ ΟΙΚΟΙ</div>${['red','gold'].map(f=>{const peace=Math.max(0,(s.ai.truce[f]||0)-s.t),pr=preview('truce',{faction:f});return `<article class="faction-card"><div class="owner-line"><span class="crest">${crest(f)}</span><span><b>${esc(FACTIONS[f].shortName)}</b><small>${REGIONS.filter(r=>s.regions[r.id].owner===f).length} φέουδα</small></span></div><p>${esc(FACTIONS[f].motto)}</p>${peace?`<span class="tag gold">ΑΝΑΚΩΧΗ · ${time(peace)}</span>`:`${costHtml(pr.cost||{money:180})}<button class="button full small" data-action="truce" data-value="${f}" ${pr.ok?'':'disabled'}>${icon('flag')}Προσωρινή ανακωχή · 3 λεπτά</button>${!pr.ok?`<p class="reason">${esc(pr.message)}</p>`:''}`}<p class="reason">Η επίθεσή σου εναντίον αυτού του οίκου τερματίζει τη συμφωνία.</p></article>`}).join('')}`;}
function renderDeck(s){$('selection-deck').classList.toggle('placing',!!view.placement);if(view.placement){$('selection-deck').innerHTML=placementDeck();return;}const selected=armyIds(),army=s.squads.filter(u=>selected.includes(u.id)&&u.hp>0);let html='';if(view.selection.kind==='army'&&army.length){const total=army.reduce((a,u)=>a+u.men,0),hp=army.reduce((a,u)=>a+u.hp,0),max=army.reduce((a,u)=>a+u.maxHp,0),formation=army[0].formation,stance=army[0].stance;html=`<span class="deck-emblem portrait">${army.length===1?unitPortrait(army[0].type):crest('player')}</span><div class="deck-info"><span class="eyebrow">Η ΔΙΑΤΑΓΗ ΣΟΥ</span><h3>${army.length===1?esc(UNIT_TYPES[army[0].type].name):army.length+' αποσπάσματα'}</h3><p>${num(total)} άνδρες · ${num(hp)} αντοχή</p>${progress(hp,max)}<div class="formation-row"><span>ΣΧΗΜΑΤΙΣΜΟΣ</span>${[['line','Γραμμή'],['column','Στήλη'],['wedge','Σφήνα']].map(([v,n])=>`<button data-action="formation" data-value="${v}" class="${formation===v?'active':''}" title="${n}">${icon(v)}${n}</button>`).join('')}<button data-action="stance" data-value="${stance==='defensive'?'aggressive':'defensive'}" title="Αλλαγή στάσης">${icon(stance==='defensive'?'shield':'attack')}${stance==='defensive'?'Άμυνα':'Έφοδος'}</button></div></div><div class="deck-actions">${[['move','move','Πορεία','M'],['attack','attack','Επίθεση','A'],['hold','hold','Κράτα','H'],['retreat','retreat','Πίσω','R']].map(([a,i,n,k])=>`<button data-action="army-command" data-value="${a}" class="${view.command===a?'active':''} ${a==='attack'?'danger':''}">${icon(i)}${n}<span class="key">${k}</span></button>`).join('')}</div>`;}else if(view.selection.kind==='node'){const n=s.nodes.find(n=>n.id===view.selection.id);if(n)html=`<span class="deck-emblem">${icon(n.type,45)}</span><div class="deck-info"><span class="eyebrow">${esc(regionById[n.regionId].name)}</span><h3>${esc(RESOURCE_NAMES[n.type])}</h3><p>${num(n.amount)} διαθέσιμα · ${n.workers} εργάτες</p>${progress(n.amount,Math.max(1,n.amount))}</div><div class="deck-actions"><button data-action="worker" data-value="${n.id}" data-delta="-1" ${n.workers?'':'disabled'}>${icon('minus')}Εργάτης</button><button data-action="worker" data-value="${n.id}" data-delta="1" ${preview('assignWorkers',{nodeId:n.id,delta:1}).ok?'':'disabled'}>${icon('plus')}Εργάτης</button><button data-action="panel" data-value="economy">${icon('people')}Εργασίες</button></div>`;}else if(view.selection.kind==='squad'){const u=s.squads.find(u=>u.id===view.selection.id);if(u)html=`<span class="deck-emblem portrait">${unitPortrait(u.type,u.owner)}</span><div class="deck-info"><span class="eyebrow">${esc(FACTIONS[u.owner].shortName)}</span><h3>${esc(UNIT_TYPES[u.type].name)}</h3><p>${u.men} άνδρες · Αντίπαλο απόσπασμα</p>${progress(u.hp,u.maxHp,'red')}</div><div class="deck-actions"><button data-action="attack-unit" data-value="${u.id}" class="danger">${icon('attack')}Επίθεση</button><button data-action="select-army" data-value="all">${icon('army')}Στρατός</button></div>`;}if(view.selection.kind==='structure'){
 const st=s.structures?.find(a=>a.id===view.selection.id);
 if(st){const b=BUILDINGS[st.type],isOwn=s.regions[st.regionId].owner==='player',job=s.jobs.find(j=>j.structureId===st.id),q=preview('build',{type:st.type,regionId:st.regionId,structureId:st.id});
 html=`<span class="deck-emblem">${icon('build',45)}</span><div class="deck-info"><span class="eyebrow">${esc(regionById[st.regionId].name)}</span><h3>${esc(b.name)}</h3><p>${st.status==='ready'?'Βαθμίδα '+st.level:st.status==='upgrading'?'Αναβάθμιση σε εξέλιξη':'Εργοτάξιο'}${job?' · '+time(job.remaining):''}</p>${job?progress(job.duration-job.remaining,job.duration,'gold'):isOwn?costHtml(q.cost):''}${isOwn&&!job&&!q.ok?'<p class="reason">'+esc(q.message)+'</p>':''}</div><div class="deck-actions">${isOwn&&st.status==='ready'?`<button data-action="upgrade-structure" data-value="${st.id}" ${q.ok?'':'disabled'}>${icon('build')}Αναβάθμιση</button>`:''}<button data-action="focus-structure" data-value="${st.id}">${icon('focus')}Εστίαση</button>${isOwn?'<button data-action="panel" data-value="build">'+icon('build')+'Έργα</button>':''}</div>`;}
 }
if(!html){const r=currentRegion(),rs=s.regions[r.id];html=`<span class="deck-emblem">${crest(rs.owner)}</span><div class="deck-info"><span class="eyebrow">${esc(FACTIONS[rs.owner].shortName)}</span><h3>${esc(r.name)}</h3><p>${rs.owner==='player'?'Το κάστρο και οι άνθρωποί του':r.subtitle}</p>${progress(rs.fortHp,rs.maxFortHp,rs.owner==='player'?'':'red')}</div><div class="deck-actions">${rs.owner==='player'?`<button data-action="panel" data-value="build">${icon('build')}Έργα</button><button data-action="recruit-panel">${icon('army')}Εκπαίδευση</button>`:`<button data-action="besiege" data-value="${r.id}" class="danger">${icon('ram')}Πολιορκία</button>`}<button data-action="select-army" data-value="all">${icon('flag')}Στρατός</button></div>`;}$('selection-deck').innerHTML=html;}
function renderMinimap(s){const c=$('minimap'),ctx=c.getContext('2d'),w=c.width,h=c.height,pad=5;const P=(x,z)=>({x:pad+(x-MAP.minX)/MAP.width*(w-pad*2),y:pad+(z-MAP.minZ)/MAP.depth*(h-pad*2)});ctx.clearRect(0,0,w,h);ctx.fillStyle='#101c1d';ctx.fillRect(0,0,w,h);for(const r of REGIONS){ctx.beginPath();r.polygon.forEach(([x,z],i)=>{const p=P(x,z);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)});ctx.closePath();ctx.fillStyle=FACTIONS[s.regions[r.id].owner].color+'4d';ctx.fill();ctx.strokeStyle='#b5b4935e';ctx.lineWidth=.65;ctx.stroke();const p=P(r.x,r.z);ctx.fillStyle=FACTIONS[s.regions[r.id].owner].color;ctx.fillRect(p.x-3,p.y-3,6,6);if(view.selection.kind==='region'&&view.selection.id===r.id){ctx.strokeStyle='#f0dca3';ctx.lineWidth=1.2;ctx.strokeRect(p.x-5,p.y-5,10,10);}}ctx.strokeStyle='#739ca17d';ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<=30;i++){const z=MAP.minZ+i*MAP.depth/30,x=9+Math.sin(z*.025)*13+Math.sin(z*.012)*5,p=P(x,z);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}ctx.stroke();for(const b of BRIDGES){const p=P(b.x,b.z);ctx.strokeStyle='#dcc991';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x-5,p.y);ctx.lineTo(p.x+5,p.y);ctx.stroke();}for(const u of s.squads){if(u.hp<=0)continue;const p=P(u.x,u.z);ctx.fillStyle=u.owner==='player'?'#b6e5ff':u.owner==='red'?'#ef826f':u.owner==='gold'?'#e7c66f':'#d7d1b2';ctx.beginPath();ctx.arc(p.x,p.y,armyIds().includes(u.id)?2.5:1.25,0,Math.PI*2);ctx.fill();}}
function renderAlerts(s){const invasion=s.squads.find(u=>u.owner!=='player'&&u.hp>0&&s.regions[regionAt(u.x,u.z)]?.owner==='player'),raid=Number.isFinite(s.ai.nextRaid)?s.ai.nextRaid-s.t:Infinity;$('raid-banner').hidden=!invasion&&!(raid>0&&raid<35);if(invasion)$('raid-banner').innerHTML=icon('warning')+`<span>Εχθρικά στρατεύματα στα εδάφη μας</span><button data-action="focus-enemy" data-value="${invasion.id}">Εντοπισμός →</button>`;else if(raid>0&&raid<35)$('raid-banner').innerHTML=icon('warning')+`<span>Οι ανιχνευτές βλέπουν εχθρική συγκέντρωση. Επίθεση σε ${time(raid)}.</span>`;$('command-hint').hidden=!view.command&&!view.placement;if(view.placement){$('command-hint').innerHTML=icon('build')+'<span>'+(view.placement.anchored?'Έλεγξε το περίγραμμα και πάτησε «Χτίσε εδώ».':'Διάλεξε έδαφος. Πράσινο: διαθέσιμο · κόκκινο: εμπόδιο.')+'</span>';return;}$('command-hint').innerHTML=view.command?`${icon(view.command==='attack'?'attack':'move')}<span>${view.command==='attack'?'Πάτησε εχθρικό απόσπασμα ή οχυρό.':'Πάτησε το σημείο προορισμού στον χάρτη.'}</span><button data-action="cancel-command" aria-label="Ακύρωση διαταγής">${icon('close')}</button>`:'';}
function render(force=false){if(rendering||(!force&&(held||performance.now()-lastRender<500)))return;rendering=true;try{const s=game.state;lastRender=performance.now();world?.setState(s);if(view.placement)refreshPlacement();$('campaign-status').innerHTML=`<span><b>Έτος 1280 · Ημέρα ${s.day}</b><small>${s.paused?'ΤΑΚΤΙΚΗ ΠΑΥΣΗ':owned().length+' ΦΕΟΥΔΑ · '+squads().length+' ΑΠΟΣΠΑΣΜΑΤΑ'}</small></span><span class="era-tag">${esc(ERAS[s.era]||ERAS[0])}</span>`;renderControlIcon('pause-button',s.paused?'play':'pause');$('pause-button').setAttribute('aria-label',s.paused?'Συνέχεια':'Παύση');renderControlIcon('sound-button',view.sound?'sound':'mute');$('sound-button').setAttribute('aria-label',view.sound?'Απενεργοποίηση ήχου':'Ενεργοποίηση ήχου');$('speed-controls').querySelectorAll('button').forEach(b=>b.classList.toggle('active',Number(b.dataset.value)===s.speed));$('map-switch').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.value===view.mapMode));renderResources(s);$('left-rail').innerHTML=NAV.map(([id,i,n])=>`<button data-action="panel" data-value="${id}" class="${view.panel===id&&view.panelOpen?'active':''}">${icon(i)}<span>${n}</span></button>`).join('');const r=currentRegion();$('map-heading').innerHTML=`<span class="eyebrow">${esc(FACTIONS[s.regions[r.id].owner].name)}</span><h2>${esc(r.name)}</h2><p><span>${esc(r.subtitle)}</span><b>${s.paused?'Η μάχη σε περιμένει.':'Η γη θυμάται τις αποφάσεις σου.'}</b></p>`;$('side-panel').classList.toggle('closed',!view.panelOpen);$('side-panel').setAttribute('aria-hidden',String(!view.panelOpen));$('side-panel').inert=!view.panelOpen||!!view.modal;if(view.panelOpen){const scroll=$('panel-body').scrollTop,focus=document.activeElement?.closest?.('[data-action]'),sig=focus?.dataset;const [ey,title]=PANELS[view.panel]||PANELS.realm;$('panel-header').innerHTML=`<span class="eyebrow">${ey}</span><h2>${title}</h2><button data-action="close-panel" aria-label="Κλείσιμο συμβουλίου">${icon('close')}</button>`;$('panel-body').innerHTML=({realm:realmPanel,build:buildPanel,economy:economyPanel,army:armyPanel,research:researchPanel,chronicle:chroniclePanel,diplomacy:diplomacyPanel}[view.panel]||realmPanel)(s);$('panel-body').scrollTop=scroll;if(sig?.action){const match=[...$('panel-body').querySelectorAll('[data-action]')].find(b=>b.dataset.action===sig.action&&b.dataset.value===sig.value&&b.dataset.delta===sig.delta);match?.focus({preventScroll:true});}}renderDeck(s);renderMinimap(s);renderAlerts(s);$('build-queue').innerHTML=s.jobs.slice(0,3).map(j=>`<article class="queue-job"><div class="stat-pair"><span>${esc(j.label||(j.kind==='train'?UNIT_TYPES[j.type]?.name:j.kind==='research'?TECHS[j.type]?.name:BUILDINGS[j.type]?.name)||j.type)}</span><b>${j.blocked?'Αναμονή':time(j.remaining)}</b></div>${progress(j.duration-j.remaining,j.duration,'gold')}${j.blocked?`<p class="job-blocked" role="status">${esc(j.blockedReason||'Περιμένει να ελευθερωθεί ο χώρος.')}</p>`:''}</article>`).join('')+(s.jobs.length>3?`<span class="queue-extra">+${s.jobs.length-3} αναθέσεις</span>`:'');$('save-status').textContent=game.storageError?'ΕΞΑΓΩΓΗ ΓΙΑ ΑΣΦΑΛΗ ΑΠΟΘΗΚΕΥΣΗ':'ΑΥΤΟΜΑΤΗ ΑΠΟΘΗΚΕΥΣΗ · v2.1.1';if(s.log[0]?.id!==lastLog){if(lastLog&&['battle','raid','capture','warning'].includes(s.log[0]?.type))tone('war');lastLog=s.log[0]?.id;}if(s.outcome&&!view.endingShown){view.endingShown=true;setTimeout(()=>showModal('ending'),0);}}finally{rendering=false;}}
function helpHtml(){return `<span class="eyebrow">ΤΟ ΒΙΒΛΙΟ ΤΟΥ ΣΤΡΑΤΗΓΟΥ</span><h2>Η πρώτη σου εκστρατεία.</h2><div class="help-grid"><div><h3>1 · Στήριξε τους ανθρώπους</h3><p>Στους Εργάτες μοίρασε τα διαθέσιμα χέρια σε τρόφιμα, ξύλο, πέτρα και σίδηρο. Στα Έργα διάλεξε κτίριο, πάτησε στο έδαφος και επιβεβαίωσε με «Χτίσε εδώ». Περίστρεψε με R ή το κουμπί περιστροφής. Το κόκκινο περίγραμμα δείχνει ακατάλληλη θέση. Επίλεξε υπάρχον κτίριο για αναβάθμιση. Οι ανάγκες του πληθυσμού και η συντήρηση του στρατού αφαιρούν πόρους συνεχώς.</p></div><div><h3>2 · Διάλεξε στρατό</h3><p>Πάτησε ένα απόσπασμα στον χάρτη ή διάλεξέ το από τον Στρατό. Το κουμπί Στρατός στο κάτω μέρος επιλέγει όλους. Οι τοξότες χρειάζονται κάλυψη και οι δορυφόροι αναχαιτίζουν το ιππικό.</p></div><div><h3>3 · Δώσε διαταγές</h3><p>Στον υπολογιστή: δεξί κλικ σε σημείο ή αντίπαλο. Στο κινητό: Πορεία ή Επίθεση και μετά πάτημα στον χάρτη. Το Κράτα κρατά τη γραμμή· το Πίσω υποχωρεί προς ασφαλές οχυρό. Μπορείς να δώσεις διαταγές και σε παύση.</p></div><div><h3>4 · Πολιόρκησε και κράτησε</h3><p>Άνοιξε πρώτα γειτονική μεθόριο, όπως το Δρυόκαστρο. Ο κριός χτυπά κοντά στα τείχη· το τρεμπουσέ βάλλει από μακριά. Αφού σπάσει η οχύρωση, χρειάζεται πεζικό στην πύλη. Εχθρική φρουρά εμποδίζει την κατάληψη.</p></div></div><h3>Τα χειριστήρια</h3><p><span class="keycap">W A S D</span> μετακίνηση κάμερας · <span class="keycap">Q E</span> περιστροφή · ροδέλα / δύο δάχτυλα για zoom · σύρσιμο για μετακίνηση · <span class="keycap">Shift</span> + σύρσιμο για επιλογή ομάδας.</p><p><span class="keycap">M</span> Πορεία · <span class="keycap">A</span> Επίθεση με επιλεγμένο στρατό · <span class="keycap">H</span> Κράτα · <span class="keycap">R</span> Υποχώρηση (περιστροφή στην κατασκευή) · <span class="keycap">Space</span> παύση · <span class="keycap">Ctrl A</span> όλος ο στρατός · <span class="keycap">Esc</span> ακύρωση / κλείσιμο.</p><div class="notice">Μία ημέρα εκστρατείας αντιστοιχεί σε 10 λεπτά στο 1×. Η μάχη σταματά όταν η σελίδα βρίσκεται στο παρασκήνιο ή είναι κλειστή. Η εκστρατεία αποθηκεύεται σε αυτόν τον browser και εξάγεται σε αρχείο από τις Ρυθμίσεις.</div><p>Στόχος: ένωσε τα εννέα φέουδα και ανέβασε την ευημερία στο 65. Το χρονικό δείχνει τα επόμενα βήματα.</p><button class="button brass full" data-action="close-modal">Στο πεδίο</button>`;}
function settingsHtml(){return `<span class="eyebrow">Η ΕΚΣΤΡΑΤΕΙΑ ΣΟΥ</span><h2>Ρυθμίσεις & αποθήκευση</h2>${view.rendererMode==='software'?'<p class="panel-description">Λειτουργία συμβατότητας: η εκστρατεία χρησιμοποιεί ελαφρύτερα μοντέλα και απλούστερο φωτισμό. Τα λεπτομερή μοντέλα, οι δυναμικές σκιές και τα πλήρη υλικά απαιτούν WebGL 2 στον browser.</p>':''}<div class="settings-row"><span>Γραφικά<small>Σκιές και ανάλυση προσαρμοσμένες στη συσκευή.</small></span><select id="quality-select" aria-label="Ποιότητα γραφικών"><option value="high" ${view.quality==='high'?'selected':''}>Υψηλά</option><option value="low" ${view.quality==='low'?'selected':''}>Απόδοση</option></select></div><div class="settings-row"><span>Ήχος ενεργειών<small>Σήματα διαταγών και ειδοποιήσεις.</small></span><button class="button small" data-action="sound">${icon(view.sound?'sound':'mute')}${view.sound?'Ενεργός':'Κλειστός'}</button></div><div class="settings-row"><span>Αποθήκευση εδώ<small>Αυτόματη και χειροκίνητη αποθήκευση.</small></span><button class="button small" data-action="save">${icon('save')}Αποθήκευση</button></div><div class="settings-row"><span>Αρχείο εκστρατείας<small>Μεταφορά σε άλλη συσκευή ή αντίγραφο.</small></span><button class="button small" data-action="export">${icon('download')}Εξαγωγή</button></div><div class="settings-row"><span>Φόρτωση αρχείου</span><button class="button small" data-action="import">${icon('upload')}Εισαγωγή</button></div><div class="settings-row"><span>Νέα εκστρατεία<small>Ξεκίνα ξανά από την Αργυρή Δρυ.</small></span><button class="button red small" data-action="reset-dialog">Νέα αρχή</button></div><div class="button-row"><button class="button" data-action="help">${icon('help')}Οδηγίες</button><button class="button" data-action="about">${icon('scroll')}Ο κόσμος</button></div><div class="version">ΦΕΟΥΔΑ 1280 · ΕΚΔΟΣΗ 2.1.1 · ΤΟΠΙΚΗ ΕΚΣΤΡΑΤΕΙΑ</div>`;}
function atlasHtml(){const s=game.state;return `<span class="eyebrow">ΕΝΝΕΑ ΦΕΟΥΔΑ · ΤΡΕΙΣ ΣΗΜΑΙΕΣ</span><h2>Οι μεθόριοι του 1280</h2><p>Διάλεξε περιοχή για να μεταφερθείς στο τρισδιάστατο πεδίο. Οι δύο γέφυρες συνδέουν τις όχθες.</p><svg viewBox="-250 -186 500 372" class="atlas-map" role="group" aria-label="Χάρτης εννέα φέουδων" style="width:100%;display:block;background:#0d1b20;border:1px solid #ac955147">${REGIONS.map(r=>{const o=s.regions[r.id].owner;return `<g data-action="atlas-region" data-value="${r.id}" role="button" tabindex="0" aria-label="${esc(r.name)}" style="cursor:pointer"><polygon points="${r.polygon.map(p=>p.join(',')).join(' ')}" fill="${FACTIONS[o].color}55" stroke="#d1bc8866" stroke-width="1.2"/><path d="M${r.x-6},${r.z-4}h3v-4h3v4h3v-4h3v13h-12Z" fill="${FACTIONS[o].color}" stroke="#ddd0aa" stroke-width="1"/><text x="${r.x}" y="${r.z+21}" text-anchor="middle" fill="#e4d1a5" style="font:10px Georgia,serif;pointer-events:none">${esc(r.name)}</text></g>`}).join('')}<path d="${Array.from({length:36},(_,i)=>{const z=MAP.minZ+i*MAP.depth/35,x=9+Math.sin(z*.025)*13+Math.sin(z*.012)*5;return(i?'L':'M')+x+','+z}).join(' ')}" fill="none" stroke="#6697a28c" stroke-width="5" pointer-events="none"/>${BRIDGES.map(b=>`<path d="M${b.x-13},${b.z}h26" stroke="#e0c795" stroke-width="4"/>`).join('')}</svg><p class="reason">Μπλε: δικά σου · Κόκκινο: Σιδηρός Λύκος · Χρυσό: Οίκος του Ήλιου · Γκρι: ελεύθερες μεθόριοι.</p>`;}
function aboutHtml(){return `<span class="eyebrow">ΜΕΣΑΙΩΝΙΚΟΣ ΚΟΣΜΟΣ · ΠΡΩΤΗ 3D ΕΚΣΤΡΑΤΕΙΑ</span><h2>Το χρονικό των στεμμάτων</h2><p>Φανταστικές ηγεμονίες με αφετηρία το 1280. Τα οχυρά, το πεζικό, το ιππικό, τα τόξα, οι καλυμμένοι κριοί και οι καταπέλτες αντιβάρου αντλούν έμπνευση από τη μεσαιωνική πολεμική. Η κυπριακή λίρα χρησιμοποιείται ως νόμισμα του παιχνιδιού.</p><p>Οι φωτογραφικές υφές πέτρας, εδάφους και ξύλου προέρχονται από το Poly Haven με άδεια CC0. Τα αρθρωτά πέτρινα κάστρα είναι του Rico Cilliers, τα έλατα των Rico Cilliers και Rob Tuytel, και η αχυροσκέπαστη κατοικία του Spiral Softworks. Οι ανθρώπινοι χαρακτήρες προέρχονται από το VibeAssets, με άδεια CC0. Η απόδοση του κόσμου γίνεται με Three.js, υπό άδεια MIT.</p><ul><li><a href="https://www.english-heritage.org.uk/learn/story-of-england/medieval/siege-warfare/?epsremainingpath=%2F" target="_blank" rel="noopener">English Heritage · Μεσαιωνικές πολιορκίες</a></li><li><a href="https://polyhaven.com/license" target="_blank" rel="noopener">Poly Haven · Άδεια υλικών</a></li><li><a href="./assets/medieval/SOURCES.json" target="_blank" rel="noopener">Υλικά, δημιουργοί και πηγές</a></li><li><a href="./assets/models/scenery-sources.json" target="_blank" rel="noopener">Κάστρα, κτίρια και φύση · προέλευση μοντέλων</a></li><li><a href="./assets/models/units-sources.json" target="_blank" rel="noopener">Χαρακτήρες · προέλευση μοντέλων</a></li><li>Κριός: <a href="https://www.wildfiregames.com/" target="_blank" rel="noopener">Wildfire Games</a>, προσαρμογή με <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">CC BY-SA 3.0</a>. <a href="./assets/models/siege-sources.json" target="_blank" rel="noopener">Πηγή και τροποποιήσεις</a>.</li></ul><p>Οι μάχες εκτελούνται στη συσκευή σου. Η έκδοση περιλαμβάνει εκστρατεία εναντίον υπολογιστή και αποθήκευση στον browser.</p>`;}
function showModal(type){if(!view.modal){view.modalResume=!game.state.paused&&view.started;game.setPaused(true);}view.modal=type;let body='';if(type==='help')body=helpHtml();else if(type==='settings')body=settingsHtml();else if(type==='atlas')body=atlasHtml();else if(type==='about')body=aboutHtml();else if(type==='reset')body='<span class="eyebrow">ΝΕΑ ΑΡΧΗ</span><h2>Νέα εκστρατεία;</h2><p>Αυτό ξεκινά νέα εκστρατεία από το 1280 και αντικαθιστά την τρέχουσα τοπική αποθήκευση.</p><div class="button-row"><button class="button" data-action="export">Εξαγωγή της τωρινής</button><button class="button red" data-action="reset-confirm">Ξεκίνα ξανά</button></div>';else if(type==='import')body='<span class="eyebrow">ΦΟΡΤΩΣΗ ΕΚΣΤΡΑΤΕΙΑΣ</span><h2>Να φορτωθεί το αρχείο;</h2><p>Η τρέχουσα εκστρατεία θα αντικατασταθεί από το επιλεγμένο αρχείο, εφόσον είναι έγκυρο.</p><div class="button-row"><button class="button" data-action="export">Εξαγωγή της τωρινής</button><button class="button brass" data-action="import-confirm">Φόρτωση</button></div>';else if(type==='ending'){const won=game.state.outcome==='victory';body=`<div class="ending"><div class="ending-crest">${crest(won?'player':'red')}</div><span class="eyebrow">ΤΟ ΧΡΟΝΙΚΟ ΤΗΣ ΕΚΣΤΡΑΤΕΙΑΣ</span><h2>${won?'Εννέα φέουδα.<br>Μία ηγεμονία.':'Η σημαία έπεσε.'}</h2><p>${won?'Η γη ενώθηκε και οι άνθρωποί της μπορούν να προοδεύσουν. Το στέμμα κερδήθηκε με χέρια, πόρους και στρατηγική.':'Η εκστρατεία τελείωσε. Μια νέα αρχή σού δίνει ξανά το Αργυρόκαστρο, τους ανθρώπους του και χρόνο να οργανώσεις διαφορετικά την άμυνα.'}</p><div class="unit-stats"><div><b>${num(game.state.stats.captured)}</b><small>ΚΑΤΑΛΗΨΕΙΣ</small></div><div><b>${num(game.state.stats.built)}</b><small>ΕΡΓΑ</small></div><div><b>${num(game.state.prosperity)}</b><small>ΕΥΗΜΕΡΙΑ</small></div></div><div class="button-row"><button class="button" data-action="export">Κράτησε το χρονικό</button><button class="button brass" data-action="reset-dialog">Νέα εκστρατεία</button></div></div>`;}$('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(type==='help'?'Οδηγίες':type==='settings'?'Ρυθμίσεις':type==='atlas'?'Χάρτης φέουδων':'Το χρονικό της εκστρατείας')}"><button class="close" data-action="close-modal" aria-label="Κλείσιμο παραθύρου">${icon('close')}</button>${body}</section></div>`;updateInput();$('modal-root').querySelector('button')?.focus();}
function closeModal(){const resume=view.modalResume;view.modal=null;view.modalResume=false;$('modal-root').innerHTML='';if(resume&&!game.state.outcome)game.setPaused(false);updateInput();render(true);}
function exportGame(){game.save();const blob=new Blob([game.exportSave()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='feouda-1280-day-'+game.state.day+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Το αρχείο της εκστρατείας εξήχθη.');}
function armyCommand(type){if(!armyIds().length)chooseArmy();if(!armyIds().length)return;if(type==='hold'||type==='retreat'){view.command=null;act('order',{ids:armyIds(),type});}else{view.command=type;view.panelOpen=false;setInsets();render(true);}}
async function onAction(event){const el=event.target.closest?.('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,value=el.dataset.value;if(!view.started&&!['begin','help','settings','close-modal','sound','about'].includes(action))return;switch(action){
case 'begin':view.started=true;store('feouda-welcomed-v1','1');$('welcome').hidden=true;game.setPaused(false);updateInput();toast('Επτά αποσπάσματα, μαζί με έναν κριό, περιμένουν. Οργάνωσε πρώτα τους εργάτες σου.');render(true);break;
case 'panel':if(view.placement)cancelPlacement({open:false});setPanel(value,!(view.panel===value&&view.panelOpen));break;
case 'close-panel':view.panelOpen=false;render(true);setInsets();break;
case 'home':world?.home();setSelection({kind:'region',id:'home'});break;
case 'zoom':world?.zoom(Number(value));break;
case 'overview':showModal('atlas');break;
case 'atlas-region':closeModal();setSelection({kind:'region',id:value},{focus:true,open:true});break;
case 'map-mode':view.mapMode=value;world?.setMapMode(value);render(true);break;
case 'select-region':setSelection({kind:'region',id:value},{focus:true,open:true});break;
case 'focus-region':world?.focus(value);break;
case 'resource':if(value==='money')setPanel('diplomacy');else{view.resourceFilter=value;setPanel('economy');}break;
case 'resource-filter':view.resourceFilter=value;render(true);break;
case 'focus-node':setSelection({kind:'node',id:value},{focus:true,open:true});break;
case 'worker':act('assignWorkers',{nodeId:value,delta:Number(el.dataset.delta)});break;
case 'build-tab':view.buildTab=value;render(true);break;
case 'build':startPlacement(value,el.dataset.region);break;
case 'placement-rotate':rotatePlacement();break;
case 'placement-move':if(view.placement){view.placement.anchored=false;refreshPlacement();render(true);}break;
case 'placement-confirm':confirmPlacement();break;
case 'placement-cancel':cancelPlacement();break;
case 'select-structure':setSelection({kind:'structure',id:value},{focus:true});break;
case 'focus-structure':{const st=game.state.structures.find(a=>a.id===value);if(st)world?.focus(st);break;}
case 'upgrade-structure':{const st=game.state.structures.find(a=>a.id===value);if(st)act('build',{type:st.type,regionId:st.regionId,structureId:st.id});break;}
case 'repair':act('repair',{regionId:value});break;
case 'army-tab':view.armyTab=value;render(true);break;
case 'recruit-panel':view.armyTab='train';setPanel('army');break;
case 'train':act('train',{type:value,regionId:el.dataset.region});break;
case 'select-squad':setSelection({kind:'squad',id:value},{add:event.shiftKey});break;
case 'select-army':chooseArmy(value||'all');break;
case 'army-command':armyCommand(value);break;
case 'cancel-command':view.command=null;render(true);break;
case 'formation':act('formation',{ids:armyIds(),formation:value});break;
case 'stance':act('stance',{ids:armyIds(),stance:value});break;
case 'besiege':if(!armyIds().length)chooseArmy();issue(regionById[value],{kind:'region',id:value});break;
case 'attack-unit':if(!armyIds().length)chooseArmy();issue(game.state.squads.find(u=>u.id===value),{kind:'squad',id:value});break;
case 'focus-enemy':{const u=game.state.squads.find(u=>u.id===value);if(u)world?.focus(u);break;}
case 'research':act('research',{type:value});break;
case 'trade':act('trade',{resource:value,type:el.dataset.trade,amount:25});break;
case 'truce':act('truce',{faction:value});break;
case 'pause':game.setPaused(!game.state.paused);render(true);break;
case 'speed':game.setSpeed(Number(value));render(true);break;
case 'sound':view.sound=!view.sound;store('feouda-sound',view.sound?'1':'0');tone();if(view.modal==='settings')showModal('settings');render(true);break;
case 'help':showModal('help');break;
case 'settings':showModal('settings');break;
case 'about':showModal('about');break;
case 'close-modal':closeModal();break;
case 'save':{const r=game.save();toast(r.message,!r.ok);break;}
case 'export':exportGame();break;
case 'import':$('import-file').click();break;
case 'import-confirm':{cancelPlacement({open:false});const r=game.importSave(view.pendingImport);view.pendingImport=null;if(r.ok){view.started=true;view.endingShown=false;view.modalResume=false;closeModal();world?.home();setSelection({kind:'region',id:'home'});if(!game.state.outcome)game.setPaused(false);}toast(r.message,!r.ok);break;}
case 'reset-dialog':showModal('reset');break;
case 'reset-confirm':cancelPlacement({open:false});view.modalResume=false;game.reset();view.endingShown=false;view.armyIds=[];view.command=null;closeModal();world?.home();setSelection({kind:'region',id:'home'});game.setPaused(false);break;
}}
document.addEventListener('click',onAction);
document.addEventListener('pointerdown',e=>{if(e.target.closest?.('[data-action],#side-panel'))held=true;});document.addEventListener('pointerup',()=>{setTimeout(()=>{held=false},50)});document.addEventListener('pointercancel',()=>held=false);
document.addEventListener('change',async e=>{if(e.target.id==='quality-select'){view.quality=e.target.value;world?.setQuality(view.quality);store('feouda-quality',view.quality);toast(view.quality==='high'?'Υψηλή ποιότητα γραφικών.':'Ρυθμίσεις γραφικών για καλύτερη απόδοση.');}if(e.target.id==='import-file'){const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){toast('Το αρχείο είναι πολύ μεγάλο.',true);return;}view.pendingImport=await file.text();showModal('import');}});
document.addEventListener('keydown',e=>{if(view.modal){const atlas=e.target.closest?.('[data-action="atlas-region"]');if(atlas&&(e.key==='Enter'||e.code==='Space'||e.key===' ')){e.preventDefault();onAction({target:atlas});return;}if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const a=[...$('modal-root').querySelectorAll('button:not(:disabled),a,select,[tabindex="0"]')];if(a.length){const first=a[0],last=a[a.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}return;}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(!view.started)return;const key=e.key.toLowerCase();if(view.placement){if(key==='escape'){e.preventDefault();cancelPlacement();return;}if(key==='r'){e.preventDefault();rotatePlacement();return;}if(key==='enter'){if(e.target.closest?.('button,[role="button"]'))return;e.preventDefault();confirmPlacement();return;}if(['m','h'].includes(key)||(e.ctrlKey||e.metaKey)){e.preventDefault();return;}if(key==='a')return;}if((e.ctrlKey||e.metaKey)&&key==='a'){e.preventDefault();chooseArmy();return;}if(e.code==='Space'||key==='p'){e.preventDefault();game.setPaused(!game.state.paused);render(true);}else if(key==='escape'){view.command=null;view.panelOpen=false;render(true);setInsets();}else if(key==='m'){e.preventDefault();armyCommand('move');}else if(key==='h'){e.preventDefault();armyCommand('hold');}else if(key==='r'){e.preventDefault();armyCommand('retreat');}else if(key==='a'&&armyIds().length){e.preventDefault();armyCommand('attack');}},true);
$('minimap').addEventListener('click',e=>{if(!view.started||view.modal)return;const r=e.currentTarget.getBoundingClientRect(),x=MAP.minX+(e.clientX-r.left)/r.width*MAP.width,z=MAP.minZ+(e.clientY-r.top)/r.height*MAP.depth;world?.focus({x,z});});
$('brand-crest').innerHTML=crest('player');$('help-button').innerHTML=icon('help');$('settings-button').innerHTML=icon('settings');$('camera-home').innerHTML=icon('home');$('overview-button').innerHTML=icon('map');
if(!view.started)game.setPaused(true);
function ready(){if(view.ready)return;view.ready=true;$('loading-screen').hidden=true;$('welcome').hidden=view.started;updateInput();render(true);}
try{world=createBattlefield($('battlefield'),{onSelect:onMapSelect,onPlacementHover:point=>movePlacement(point),onPlacementPick:point=>movePlacement(point,true),onGround:point=>{if(view.placement)movePlacement(point,true);else if(view.command)issue(point)},onContext:(point,target)=>{if(!view.placement)issue(point,target)},onBoxSelect:ids=>setSelection({kind:'army',ids}),onReady:()=>queueMicrotask(ready),onAssetStatus:status=>{
 view.assetStatus=status;const shell=$('game-shell');shell.dataset.assetsLoaded=String(status.loaded);shell.dataset.assetsTotal=String(status.total);shell.dataset.assetsFailed=String(status.failed?.length||0);
 if(status.phase==='loading')$('loading-message').textContent='Φόρτωση λεπτομερών μοντέλων · '+status.loaded+' / '+status.total;
 if(status.phase==='partial')toast('Ορισμένα λεπτομερή μοντέλα δεν φορτώθηκαν. Ανανέωσε τη σελίδα για νέα προσπάθεια.',true);
 },onMode:mode=>{view.rendererMode=mode;$('game-shell').dataset.renderer=mode;if(mode==='software')$('loading-message').textContent='Στήνεται το πεδίο σε λειτουργία συμβατότητας.';},onError:error=>{bootFailed=true;$('loading-message').textContent='Η τρισδιάστατη απεικόνιση δεν μπόρεσε να ξεκινήσει. Χρειάζεται ενεργό WebGL 2. '+(error?.message||'');}});world.setState(game.state);world.setSelection(view.selection);world.setQuality(view.quality);setInsets();world.setInputEnabled(view.started);}
catch(error){bootFailed=true;console.error('Feouda renderer failed',error);$('loading-message').textContent='Η τρισδιάστατη απεικόνιση δεν φορτώθηκε. Ενεργοποίησε την επιτάχυνση γραφικών και ανανέωσε τη σελίδα.';}
game.subscribe(()=>{world?.setState(game.state);render();});render(true);
setInterval(()=>{const t=performance.now(),dt=Math.min((t-lastStep)/1000,.5);lastStep=t;if(!document.hidden&&view.started&&view.ready&&!bootFailed)game.step(dt);render();},50);
document.addEventListener('visibilitychange',()=>{lastStep=performance.now();if(document.hidden)game.save();});window.addEventListener('pagehide',()=>game.save());window.addEventListener('resize',()=>{setInsets();render(true)});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{}));
window.feouda={getState:()=>JSON.parse(JSON.stringify(game.state)),getView:()=>JSON.parse(JSON.stringify(view)),getMap:()=>world?.getDebugState()};
